        for q in range(0,k+1):
         for e in range(1,4):
          for f in range(0,min(e-1,1)+1):
           for g in range(0,min(q,2*(2*f+1))+1):
            cells.append((n,l,k,q,e,f,g,S2))
    return cells
L8=build8(); L9=[c+(s,) for c in L8 for s in range(0,c[6]+1)]

def allowed_2S(l,N):
    orb=[(ml,ms) for ml in range(-l,l+1) for ms in (0,1)]
    if N==0: return {0}
    MS=Counter()
    for det in combinations(range(len(orb)),N):
        up=sum(orb[i][1] for i in det); MS[2*up-N]+=1
    out=set(); counts=dict(MS)
    for m in sorted([x for x in MS if x>=0],reverse=True):
        while counts.get(m,0)>0:
            out.add(m); mm=m
            while mm>=-m: counts[mm]-=1; mm-=2
    return out

def closure_fails(cells):
    S=set(cells); jf=mf=0; cl=list(cells)
    for i in range(len(cl)):
        a=cl[i]
        for b in cl[i+1:]:
            if tuple(max(x,y) for x,y in zip(a,b)) not in S: jf+=1
            if tuple(min(x,y) for x,y in zip(a,b)) not in S: mf+=1
    return jf,mf

def R_defect(cells):
    """E(X) = |R(X)| - |X| with pairwise monotone bounds, per §1.1"""
    d=len(cells[0]); A=[sorted(set(c[i] for c in cells)) for i in range(d)]
    import itertools
    # bounds phi_ij(v) = max{x_i : x in X, x_j <= v}
    phi={}
    for i in range(d):
        for j in range(d):
            if i==j: continue
            for v in A[j]:
                sel=[c[i] for c in cells if c[j]<=v]
                phi[(i,j,v)]=max(sel) if sel else None
    Sset=set(cells); count=0
    for x in itertools.product(*A):
        ok=True
        for i in range(d):
            for j in range(d):
                if i==j: continue
                b=phi[(i,j,x[j])]
                if b is None or x[i]>b: ok=False; break
            if not ok: break
        if ok: count+=1
    return count-len(cells)

# ---- [4] Λ₉′ : adjoin the second admissible constraint 2S′ ≤ 2f+1 ----
L9p=[c for c in L9 if c[8] <= 2*c[5]+1]
jf,mf=closure_fails(L9p)
phys=sum(1 for c in L9p if c[8] in allowed_2S(c[5],c[6]))
E=R_defect(L9p)
print(f"[4] Λ₉′ = Λ₉ ∩ {{2S′ ≤ 2f+1}}:")
print(f"    cells {len(L9p)} (removed {len(L9)-len(L9p)})   join fails {jf}   meet fails {mf}   E(Λ₉′) = {E}")
print(f"    realisable on ninth axis: {phys} ({100*phys/len(L9p):.1f}%)   [Λ₉ was 63.7%]")
print(f"    validity check: min(g,4f+2−g) ≤ 2f+1 always — cells cut are exactly f=0,g=2,2S′=2:",
      all((c[5],c[6],c[8])==(0,2,2) for c in L9 if c not in set(L9p)) if len(L9)-len(L9p)>0 else "n/a")
print(f"    constraint graph: 9 nodes, 9 edges (f–g–2S′–f cycle) — NOT a tree")

# ---- [5] the recoding: u = (g − 2S′)/2 on the physical region ----
physcells=[c for c in L9 if c[8] in allowed_2S(c[5],c[6])]
recoded=[]
bad=0
for c in physcells:
    g,S2p=c[6],c[8]
    if (g-S2p)%2: bad+=1; continue
    recoded.append(c[:8]+((g-S2p)//2,))
jf,mf=closure_fails(recoded)
print(f"\n[5] physical region recoded, ninth axis u=(g−2S′)/2 (pair count):")
print(f"    parity violations in physical region: {bad} (must be 0)")
print(f"    cells {len(recoded)}   join fails {jf}   meet fails {mf}")
if jf==0 and mf==0:
    print(f"    E(recoded) = {R_defect(recoded)}")
else:
    # locate mechanism of failure
    S=set(recoded); ex=None
    for i in range(len(recoded)):
        for jx in range(i+1,len(recoded)):
            a,b=recoded[i],recoded[jx]
            m=tuple(min(x,y) for x,y in zip(a,b))
            if m not in S: ex=(a,b,m,'meet'); break
            j=tuple(max(x,y) for x,y in zip(a,b))
            if j not in S: ex=(a,b,j,'join'); break
        if ex: break
    print(f"    first failure ({ex[3]}): a(f,g,u)={ex[0][5],ex[0][6],ex[0][8]}  b={ex[1][5],ex[1][6],ex[1][8]}  -> {ex[2][5],ex[2][6],ex[2][8]}")
