from itertools import combinations, product
from collections import Counter
import random

# ---------- term machinery: exact LS decomposition of l^N ----------
def terms(l, N):
    """Counter of (2S, 2L) with multiplicity, by M-counting."""
    orb=[(ml,ms) for ml in range(-l,l+1) for ms in (0,1)]
    M=Counter()
    for det in combinations(range(len(orb)), N):
        ML=sum(orb[i][0] for i in det); up=sum(orb[i][1] for i in det)
        M[(2*ML, 2*up-N)]+=1
    T=Counter(); M=dict(M)
    while any(v>0 for v in M.values()):
        (ml2,ms2)=max((k for k,v in M.items() if v>0), key=lambda t:(t[1],t[0]))
        L2,S2=ml2,ms2
        T[(S2,L2)]+=1
        for a in range(-L2,L2+1,2):
            for b in range(-S2,S2+1,2):
                M[(a,b)]-=1
    return T

def seniority_pairs(l, N):
    """allowed (v, 2S) for l^N: seniority-v terms = terms(l^v) - terms(l^(v-2))."""
    out=set()
    v=N
    while v>=0:
        tv=terms(l,v); tvm=terms(l,v-2) if v>=2 else Counter()
        diff=tv-tvm
        for (S2,L2),m in diff.items():
            if m>0: out.add((v,S2))
        v-=2
    return out

def J_pairs(l, N):
    """allowed (2S, 2J) for l^N."""
    out=set()
    for (S2,L2),m in terms(l,N).items():
        for J2 in range(abs(L2-S2), L2+S2+1, 2):
            out.add((S2,J2))
    return out

# ---------- base lattices ----------
def build8():
    cells=[]
    for n in range(1,4):
     for l in range(0,min(n-1,1)+1):
      for k in range(1,min(2*(2*l+1),3)+1):
       for S2 in range(0,k+1):
        for q in range(0,k+1):
