from itertools import combinations
from collections import Counter

def terms(l,N):
    if N==0: return Counter({(0,0):1})
    orb=[(ml,ms) for ml in range(-l,l+1) for ms in (0,1)]
    M=Counter()
    for det in combinations(range(len(orb)),N):
        M[(2*sum(orb[i][0] for i in det), 2*sum(orb[i][1] for i in det)-N)]+=1
    T=Counter(); M=dict(M)
    while any(v>0 for v in M.values()):
        (L2,S2)=max((k for k,v in M.items() if v>0), key=lambda t:(t[1],t[0]))
        T[(S2,L2)]+=1
        for a in range(-L2,L2+1,2):
            for b in range(-S2,S2+1,2): M[(a,b)]-=1
    return T

