            if S2p in ex: continue
            par=(S2p-g)%2!=0
            fold=S2p>min(g,cap-g)
            if par and fold: gapB+=1
            elif par: gapP+=1
            elif fold: gapF+=1
print(f"    axis 9 (2S′≤g) fibre-values: {tot}  gap: parity-only {gapP}, fold-only {gapF}, both {gapB}, other {tot-gapP-gapF-gapB - sum(1 for f in (0,1) for g in range(0,min(3,2*(2*f+1))+1) for s in range(0,g+1) if s in allowed_2S(f,g))}")

